insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 1, 'What does the Expert tier add to the Professional tier''s work?', '["It replaces Easy%Ro with a basin-specific kinetic scheme.", "It produces the temperature histories itself and turns conversion into mass.", "It adds migration pathways and trap-fill calculations on top of the forward model.", "It calibrates the kerogen spectra against pyrolysis data."]'::jsonb, 1, 'The forward model marches the basin through 150 Ma, generating every track, and adds potential mass and expulsion. Migration stays downstream of the course, and the kinetics are never re-derived.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 2, 'How many values does the Expert capstone grade, and from which layer?', '["Seven, one per layer plus the signature.", "Six, two from each of three layers.", "Four, from the source shale.", "Six, all read from the source shale."]'::jsonb, 3, 'Final Ro, temperature, TR, generated and expelled mass, and the erosion signature, all for the source rock at present day.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 3, 'The sixth graded field cannot come from a single run because', '["it is a difference between two model states.", "it needs the Python oracle as the second operand.", "the engine cannot store two runs at once.", "it is measured, not modelled."]'::jsonb, 0, 'And without the event. The erosion signature is defined as with-minus-without on final source Ro. Only a controlled pair of runs defines it.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 4, 'The reference basin''s four layers, oldest first, are', '["Upper Shale, Mid Sand, Source Shale, Base Sand.", "Source Shale, Base Sand, Upper Shale, Mid Sand.", "Base Sand, Source Shale, Mid Sand, Upper Shale.", "Base Sand, Mid Sand, Source Shale and then Upper Shale."]'::jsonb, 2, 'Deposited 150-140, 140-120, 120-80 and 80-20 Ma. The third option is the stack top-down at present day, not deposition order.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 5, 'The source shale''s richness parameters are', '["TOC 4 percent and hydrogen index 500, Type III.", "TOC 2 percent and hydrogen index 300, Type II.", "TOC 4 percent and hydrogen index 500, Type II.", "TOC 500 and hydrogen index 4."]'::jsonb, 2, 'A rich marine source: 4 percent organic carbon, HI 500 mg hydrocarbon per g of carbon, and the Type II library spectrum.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 6, 'The layer thicknesses in the input describe', '["present-day thicknesses.", "depositional thicknesses at the surface.", "average thicknesses over the basin''s history, weighted by residence time at each depth.", "solid thicknesses directly."]'::jsonb, 0, 'Which invariant solid thicknesses are derived once. The observable a well measures is today''s stack. The engine derives the conserved grain from it top down, guaranteeing the model reproduces present geometry exactly.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 7, 'The source shale''s solid thickness is', '["728.8203220981025 m, its bulk thickness when it sat at the surface.", "400 m, equal to its present thickness.", "274.3599416810648 m, like the phantom''s.", "345.33834344581027 m inside its 400 m of present rock."]'::jsonb, 3, 'Grain from the present 2800-3200 m position. The 274.36 figure is the 600 m phantom''s solid content, and 728.82 is the source''s bulk thickness when it sat at the surface.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 8, 'The reference basin''s surface temperature is', '["10 degC, as in the beginner heat column.", "15 degC, set in the project settings.", "20 degC, the engine default.", "0 degC at the seabed."]'::jsonb, 1, 'Three surface temperatures circulate in this course: 15 is this basin''s setting, 10 the Associate fixture''s, 20 the engine''s fallback when settings omit it.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 9, 'The heat-flow history is specified as', '["80 at 150 Ma, 70 at 100, 65 at 50, 60 at 0 mW/m2.", "a constant 60 mW/m2.", "80 mW/m2 decaying exponentially with a 50 Ma half-life.", "60 at 150 Ma rising to 80 at present."]'::jsonb, 0, 'Linearly in age. Four dated points, piecewise linear, cooling as a stretched lithosphere re-thickens. The engine divides by 1000 to work in W/m2.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 10, 'The interpolated heat flow at 120 Ma is', '["76 mW/m2, read 0.4 of the way along the segment.", "74 mW/m2.", "70 mW/m2.", "77 mW/m2."]'::jsonb, 1, '120 sits 0.6 of the way down the 150-to-100 segment: 80 + 0.6 x (70 - 80) = 74. At 130 Ma the value is 76.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 11, 'Without the erosion event, the source''s temperature peaks at', '["149.76037539670858 degC at present day.", "168.51433459340572 degC at 18 Ma.", "165.60511032656453 degC at 76 Ma.", "180 degC at 150 Ma."]'::jsonb, 2, 'The last 76 Ma one long cooling. Early high heat flow acting on the newly completed overburden. The 168.51 peak at 18 Ma belongs to the run WITH the event; 149.76 is the present value, not a maximum.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 12, 'The panel''s one control is', '["the surface temperature.", "the kerogen type of the source.", "the heat-flow history''s youngest point.", "the erosion amount at 10 Ma."]'::jsonb, 3, '0, 300, 600 or 900 m. Sensitivity to the event is the tier''s teaching instrument. The reference setting is 600 m; the no-event twin always runs alongside.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 13, 'On the panel''s mass chart, expelled mass jumps where', '["the burial track rebounds at 10 Ma and the regrown bucket releases its stored excess.", "the heat flow crosses 65 mW/m2.", "the source crosses Ro 1.0.", "the dashed cap dips below the rising generation curve during the phantom decade."]'::jsonb, 3, 'The squeeze: a smaller bucket under standing generation expels the difference, and the monotone rule keeps it expelled through the rebound.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 14, 'At age zero, the panel''s temperature and reflectance tracks show', '["both tracks holding their hot-decade maxima.", "both tracks converged to the no-event run.", "temperature back to within a ten-thousandth of a degree of the no-event run, reflectance still 0.0567 above it.", "temperature still elevated from the hot decade while the reflectance curves have converged onto the no-event run."]'::jsonb, 2, 'The thermometer forgets and the reflectance remembers. The terminal gap between the solid and faint Ro curves is the capstone''s sixth field.'),
  ('basin', 'advanced', 'module', 'm01-the-reference-basin', 15, 'Which inputs would a well NOT directly constrain?', '["The present-day layer thicknesses.", "The heat-flow history.", "The source''s TOC and hydrogen index, which only regional analogues can supply.", "The lithologies of the stack."]'::jsonb, 1, 'Is why it becomes calibration''s free parameter. Tops, richness and lithology are measured; basal heat flow is inferred, bounded by analogues and tuned within physical limits against measured maturity.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 1, 'The forward march steps', '["from present day backward to 150 Ma.", "from 150 Ma to zero in 1 Ma steps.", "in 0.01 Ma steps throughout.", "adaptively, finer during events."]'::jsonb, 1, 'Layer''s start age first. DT_MA = 1. The 0.01 Ma convention belongs to the Professional tier''s ramp fixtures, not the basin march.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 2, 'Each step, the model performs, in order,', '["temperature solve first, then a geometry correction applied from the new thermal state.", "kinetics, then geometry, then temperature.", "one action chosen by the event calendar.", "layer census, geometry stack, thermal grid, temperature solve, kinetics and recording."]'::jsonb, 3, 'Which layers exist; stack them top down from solid thicknesses; build the grid; solve heat; advance both clocks per layer at its centre temperature and record.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 3, 'A layer is deposited', '["in full at its ageStart, instantaneously.", "linearly across its deposition window, at a constant rate.", "at a rate set by its lithology.", "when the layer above it starts."]'::jsonb, 0, 'Version one''s documented convention. The Upper Shale''s 1600 m arrive in the single 80 Ma step, though its window in the input reads 80 to 20.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 4, 'When the Upper Shale lands at 80 Ma, the source''s top depth moves', '["from 2800 to 3128.79 m.", "from 0 to 1467.71 m.", "from 1467.7117658564923 m to 2800 m in one step.", "gradually down to 2800 m across the sixty steps of the window."]'::jsonb, 2, 'The staircase''s biggest tread. The 0-to-1467.71 move happened at 120 Ma with the Mid Sand; 2800-to-3128.79 is the phantom''s arrival at 20 Ma.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 5, 'At that arrival, the source''s recorded TR jumps from about 0.0205 to 0.269 in one step because', '["the recording is cumulative across all of the steps the deposition window skipped.", "the kerogen spectrum was switched at 80 Ma.", "the step compresses sixty megayears of real deposition into an instant of deep, hot burial.", "the engine interpolates TR between events."]'::jsonb, 2, 'One step at around 153 degC does what the real gradual burial spread over the shale''s accumulation. Model onset dates read sharper than the rock experienced them.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 6, 'The geometry at any step is', '["a pure function of which layers exist, recomputed from invariant solid thicknesses.", "carried forward from the previous step, with incremental burial added on top.", "read from a precomputed table of depths.", "exact only at present day."]'::jsonb, 0, 'No memory in the geometry stage: stack whoever exists, top down, Newton-solving each thickness from conserved grain at its current burial.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 7, 'At deposition the source was 728.8203220981025 m thick; today it is 400 m. What is conserved?', '["Its thickness at maximum burial, per the hysteresis rule.", "Its bulk volume.", "Its porosity profile.", "Its solid thickness of 345.33834344581027 m."]'::jsonb, 3, 'Grain is the invariant currency. Thickness and porosity are functions of current burial; 45 percent of the bulk thickness vanished while no grain did.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 8, 'The first thermal solve of the run is', '["backward Euler from a zero-degree start.", "steady state; every later step is backward Euler from the previous profile.", "skipped entirely, since a single fresh layer can hold no internal gradient.", "an analytic two-layer formula."]'::jsonb, 1, 'With no history behind it, the opening step takes the settled answer. Afterwards each step relaxes the old profile toward the new boundary conditions over 1 Ma.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 9, 'Newly deepened rock below the old grid''s reach gets its first temperature estimate from', '["extending the old profile along its basal gradient.", "the surface temperature.", "the steady solution of the new geometry at the new basal flux.", "zero, corrected next step."]'::jsonb, 0, 'The basal-gradient extrapolation. Whether it over- or undershoots the eventual steady answer decides the direction of the following relaxation.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 10, 'After the Mid Sand lands at 120 Ma, the source''s temperature reads 96.995 then relaxes DOWN to about 94.04, while after the Upper Shale it climbs from 153.07 toward the mid-160s. Why the opposite directions?', '["Sandstone cools basins and shale heats them.", "The first estimate can land on either side of the new steady profile.", "The heat flow rose at 120 Ma and fell at 80 Ma.", "The engine deliberately alternates solver directions on successive deposition events."]'::jsonb, 1, 'The transient relaxes toward it from wherever it starts. The extrapolated guess overshot after the conductive sand''s arrival and undershot under the insulating shale. Both relaxations are honest transient physics.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 11, 'Kinetics run at', '["each thermal cell separately.", "the layer''s top temperature.", "the temperature interpolated at each layer''s centre depth.", "the column''s average temperature, weighted by each cell''s heat capacity."]'::jsonb, 2, 'Value per layer per step. One kinetic state per layer means one representative temperature, the midpoint. Thick sources can be subdivided in the input when internal gradients matter.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 12, 'The graded final temperature, 149.76037539670858 degC, is read at', '["the depth of the source''s maximum burial, 3324 m.", "3200 m, the source''s base.", "2800 m, the source''s top.", "3000 m, the present centre of the source."]'::jsonb, 3, 'Centre convention: halfway between 2800 and 3200. The layer''s internal spread is about ten degrees, invisible to a single-Ro-per-layer model.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 13, 'The model''s compaction on unroofing is', '["disabled during erosion events.", "hysteretic: porosity freezes at maximum burial.", "plastic below 2000 m and elastic above.", "elastic: porosity follows depth both ways."]'::jsonb, 3, 'Unroofed layers re-expand. The documented version-one limitation, with max-burial hysteresis the recorded follow-on. The source returns to 400 m and phi 0.137 after the phantom vanishes.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 14, 'Where does elastic rebound bite hardest in this fixture?', '["The erosion signature is erased.", "The final temperature shifts by tens of degrees.", "The retention cap regrows after the event.", "The solid thicknesses drift."]'::jsonb, 2, '3858.026119789524 to 4662.34280519763 kg/m2. Temperature and Ro effects are marginal here, and grain is invariant by construction. The regrown bucket is the convention''s real footprint, though the graded expelled mass was locked in before it mattered.'),
  ('basin', 'advanced', 'module', 'm02-the-forward-march', 15, 'A step-shaped burial track should be read as', '["evidence of episodic, catastrophic sedimentation punctuating long quiet intervals.", "a convention of instant deposition, not evidence the basin did anything suddenly.", "a bug to be reported.", "an artefact of the plotting."]'::jsonb, 1, 'The staircase is version one''s documented trade: within-window schedules are data nobody has. Knowing it prevents over-reading sharp model onsets.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 1, 'An erosion event is specified by', '["a start age, an end age and a constant removal rate between the two.", "an age and an amount: 10 Ma and 600 m for the reference.", "the identity of the layer removed.", "a fraction of the top layer."]'::jsonb, 1, 'Two numbers. Everything else about the vanished section, its timing and lithology, is inferred by the engine''s convention.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 2, 'The phantom layer''s solid thickness is', '["zero, since it is never reported.", "600 m, the amount itself.", "345.33834344581027 m, exactly the same grain content as the source shale''s.", "274.3599416810648 m, from 600 m of shale deposited at the surface."]'::jsonb, 3, 'The Associate integral on 600 m of fresh surface shale. It is mechanically real rock while it exists; only the reporting excludes it.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 3, 'The phantom is deposited at', '["20 Ma, the youngest ageEnd among layers older than the event.", "10 Ma, the event age.", "80 Ma, arriving together with the Upper Shale''s own instantly deposited section.", "an age the user specifies."]'::jsonb, 0, 'The convention reads the vanished section as accumulating immediately after preserved deposition ended. Quoted erosion timings are conditional on it.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 4, 'During the phantom decade the source''s bottom reaches', '["3800 m, the base of the 600 m phantom section stacked on today''s 3200 m.", "3200 m, its present bottom.", "3519.372263771036 m, its deepest position of the whole history.", "3128.7948635060234 m."]'::jsonb, 2, '319 m deeper than today. The 3128.79 figure is the source''s TOP during the decade, and 3200 is its present bottom.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 5, 'The source''s lifetime temperature maximum, with the event, is', '["167.24573484238402 degC at 11 Ma.", "165.60511032656453 degC at 76 Ma, the early peak.", "168.51433459340572 degC at 18 Ma.", "153.84048634909556 degC at 10 Ma."]'::jsonb, 2, 'The hot decade''s peak. The 165.61 value at 76 Ma is the maximum of the run WITHOUT the event; 167.25 and 153.84 are the decade''s last step and the rebound step.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 6, 'Extra burial at 18 Ma beat the early 76 Ma peak by only 2.9 degrees because', '["it arrived when the basal heat flow had decayed to about 61 mW/m2.", "the phantom conducts heat too well.", "the transient never caught up.", "the deeper rock sits proportionally closer to the cold seabed boundary condition."]'::jsonb, 0, 'Each metre of depth buys temperature in proportion to the current supply. The same phantom under the young basin''s 67-plus flux would have pushed far past 180.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 7, 'At the 10 Ma removal, the source''s temperature', '["is not recomputed until 5 Ma.", "rises as insulation is removed.", "snaps instantly to the steady value of the freshly unroofed column''s geometry.", "drops 13.4 degrees in one step and keeps easing toward 149.76."]'::jsonb, 3, '167.24573484238402 to 153.84048634909556 in the step, then the warm tail drains over following steps: the transient relaxing downward after unroofing.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 8, 'Present-day source temperatures with and without the event differ by', '["0.0567 degrees, mirroring the reflectance signature on the thermal channel.", "about 0.0001 degrees: 149.76037539670858 against 149.76027256253775.", "2.9 degrees.", "13.4 degrees."]'::jsonb, 1, 'Ten quiet megayears erase the thermal difference almost completely. The 0.0567 is the REFLECTANCE difference, a different instrument entirely.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 9, 'Thermal memory in this basin is short because', '["conductive relaxation across basin depths completes in about a megayear.", "the heat flow resets each step.", "circulating formation water carries the stored heat out of the column within a single step.", "the engine truncates old profiles."]'::jsonb, 0, 'Diffusion time across a couple of kilometres is under a megayear, so a column forgets a thermal insult within a few megayears of the geometry going quiet.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 10, 'Maturity memory is permanent because', '["the engine stores every historical profile.", "the bin states only drain and the read-out additionally holds its maximum.", "reflectance is measured, not modelled.", "the kerogen state holds a backup copy of the vitrinite state at every step of the march."]'::jsonb, 1, 'Two ratchets: kinetic states never refill, and Ro is clamped at max(state.Ro, ro). The hot decade''s drainage survives the cooling that erased its cause.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 11, 'The erosion signature is defined as', '["the Ro change across the 10 Ma step.", "the difference in final source temperature between the two runs at present day.", "final source Ro with the event minus final source Ro without it.", "the drop in expelled mass without the event."]'::jsonb, 2, '0.05665081052235643. With-minus-without, same layer, same date, positive. 1.6718288798752388 - 1.6151780693528823, graded to 0.001.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 12, 'Shared simplifications cancel in the two-run difference because', '["the oracle removes them.", "the engine subtracts them explicitly.", "they are individually too small to matter in either one of the two operand runs.", "they bias both runs alike, leaving only the event''s own causal chain."]'::jsonb, 3, 'Instant deposition, rebound, the centre convention: all first-order common to both operands. That is why the signature is better behaved than either absolute Ro.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 13, 'The signature was actually acquired', '["in the last megayear.", "at the 10 Ma removal step.", "steadily across the whole 150 Ma.", "between about 18 and 11 Ma."]'::jsonb, 3, 'Carried unchanged since by the ratchet. Differencing the two Ro histories: about 0.006 of gap by 20 Ma, 0.058 by 10 Ma, 0.0567 at present. The hot decade wrote it; nothing after could.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 14, 'The signatures at eroded amounts 300 / 600 / 900 m are', '["0.0567 at every amount.", "0.0284 / 0.0567 / 0.0851: linear in the amount.", "0.0144 / 0.0567 / 0.1529: convex.", "0.1529 / 0.0567 / 0.0144: shrinking with amount."]'::jsonb, 2, 'Faster than linearly. Each extra slab lands the source on a hotter, exponentially faster part of the Arrhenius curve. Doubling 300 to 600 multiplied the signature by 3.94.'),
  ('basin', 'advanced', 'module', 'm03-the-erosion-event', 15, 'Convexity means small erosion events are', '["easier to see than large ones, their kinetic signal being much less saturated at the low end.", "structurally harder to recover from maturity, quite apart from measurement scatter.", "impossible at 10 Ma.", "linear in their signature."]'::jsonb, 1, 'The curve''s slope shrinks toward zero amount, so metres of missing section buy least Ro exactly where events are smallest. Below roughly 150 m this fixture''s signature sinks under laboratory scatter.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 1, 'The generative potential formula is', '["bulk density x thickness x TOC x HI.", "grain density x solid thickness x TOC/100 x HI/1000.", "solid thickness x porosity x TOC/100.", "grain density x bulk thickness x TOC/100 x HI/1000, at present-day geometry."]'::jsonb, 1, '2720 x 345.33834344581027 x 0.04 x 0.5 = 18786.405883452077 kg/m2 for the fixture: the pore-free rock inventory scaled by richness.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 2, 'The potential is computed on SOLID thickness because', '["porosity holds the hydrocarbon.", "solid rock is denser than bulk rock.", "the capstone grades solid quantities rather than bulk ones.", "organic inventory rides the conserved grain."]'::jsonb, 3, 'The potential constant through burial. On bulk thickness the potential would change as pores close: 728.82 m at deposition against 400 m today for the same rock. Grain conservation promoted into geochemistry.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 3, 'Kerogen type enters the mass chain', '["only through the kinetics that set how fast the potential converts, never in the potential itself.", "as a direct multiplier on the potential, richer types carrying proportionally larger inventories than leaner ones.", "through the grain density.", "nowhere; type is a display label."]'::jsonb, 0, 'The potential is pure inventory. Type II versus III changes the schedule of conversion, not the ceiling.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 4, 'Generated mass at any step equals', '["the integral of the layer''s temperature over the time it has spent buried.", "the potential minus the retention cap.", "the constant potential times the current transformation ratio.", "expelled mass plus the cap."]'::jsonb, 2, 'M_gen = M_pot x TR(t), exactly. At present day: 18786.405883452077 x 0.7423743797385286 = 13946.54641524398.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 5, 'The single most productive megayear of the basin''s history is', '["the final step.", "the 18 Ma hot-decade peak, the basin''s lifetime temperature maximum at the source.", "the 80 Ma step, about five thousand kg/m2 generated as the Upper Shale lands.", "the 120 Ma Mid Sand arrival."]'::jsonb, 2, 'TR jumps 0.0205 to 0.269 in that step, the deposition convention compressing the real gradual burial. The hot decade adds only 523 kg in ten steps.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 6, 'The hot decade''s generation contribution is about', '["523 kg/m2, under 4 percent of the total.", "5000 kg/m2, the basin''s largest pulse.", "1258 kg/m2, the event''s charge contribution.", "zero: generation had finished."]'::jsonb, 0, 'The stall at work even at 168 degC. TR moves 0.7124 to 0.7403 across the decade. The kerogen''s remaining potential sits in its highest bins; the event''s charge significance comes through the cap instead.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 7, 'The retention cap formula is', '["solid thickness x average porosity x 0.1 x 850 kg/m3.", "thickness x TOC x HI.", "porosity x depth x grain density.", "thickness x average porosity x 0.1 x 850 kg/m3."]'::jsonb, 3, 'Pore volume per unit area, at the 10 percent expulsion saturation threshold, at the 850 kg/m3 reference hydrocarbon density. Average porosity is the mean of the top and bottom Athy values.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 8, 'At deposition the source''s bucket held 32970 kg/m2; by 80 Ma it held 4662. The shrinkage means', '["the source lost grain to compaction.", "burial makes sources leakier while making them more productive.", "the expulsion saturation threshold itself fell steadily with increasing depth.", "the engine rescaled the cap at 80 Ma."]'::jsonb, 1, 'Both variable factors, thickness and porosity, fall with burial while temperature and generation rise. The bucket shrinks exactly as the stream into it swells.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 9, 'Expulsion begins', '["in the same 80 Ma step that deposits the Upper Shale.", "at 120 Ma, in the same step that the source''s first generation appears.", "at 11 Ma, with the squeeze.", "only after the erosion event."]'::jsonb, 0, '5054.728 generated against a 4662.343 cap leaves 392.38532834076887 expelled. The seal''s deposition triggered the charge twice over, heating the source and squeezing its bucket in one step.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 10, 'Final expelled mass, 10048.985378825158 kg/m2, equals', '["final generation minus the present cap.", "generation at 11 Ma minus the squeezed cap.", "the potential times the expulsion efficiency threshold.", "final generation minus retained oil at the brim."]'::jsonb, 1, '13907.011498614682 - 3858.026119789524, exactly. An exact float64 identity, set at the last step of the phantom decade. The present-day subtraction gives 9284.204, which is NOT the graded value.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 11, 'At 10 Ma the cap regrows to 4662.343 while generation stands at 13912.534. Expelled mass', '["resumes climbing immediately.", "falls to 9250.191.", "stays at 10048.985378825158.", "resets to the new gen-minus-cap."]'::jsonb, 2, 'Expulsion is a running maximum. max(previous, gen - cap): the regrown bucket leaves the rock under-full, and expulsion cannot resume until generation exceeds the cap plus what already left.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 12, 'Of the event''s 1258.64959465631 kg/m2 charge contribution,', '["half came from each mechanism.", "all 1258.65 kilograms of it came from the hot decade''s extra generation alone.", "all of it came from the squeeze.", "764.78 came from the cap squeeze and only 493.87 from extra generation."]'::jsonb, 3, 'Three fifths is mechanical: the bucket was 804.3 kg smaller while the oil stood generated. Erosion is a charge mechanism, not just a maturity anecdote.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 13, 'A cap squeeze converts retained inventory into charge, so it pays exactly when', '["the basin is at its lifetime maximum heat flow when the squeeze arrives.", "the source is immature.", "generation has not yet begun.", "the rock is holding oil at or near its cap when the squeeze arrives."]'::jsonb, 3, 'Move the event before generation and the squeezed bucket is empty. The timing condition is the screening question for real basins with unroofing histories.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 14, 'The three memory behaviours of the model''s state variables are', '["all three memoryless.", "all three monotone.", "temperature none, maturity monotone in its own maximum, expulsion monotone in gen-minus-cap.", "temperature monotone in its own maximum, with both of the other two state variables memoryless."]'::jsonb, 2, 'Three instruments keeping three diaries. Expulsion''s recorded quantity includes geometry, which is why it can register events maturity barely notices.'),
  ('basin', 'advanced', 'module', 'm04-generation-and-expulsion', 15, 'The question to ask any monotone state variable is', '["what its present value is.", "when its maximum was set.", "whether its present-day value sits above the graded tolerance band for its field.", "which layer owns it."]'::jsonb, 1, 'That date is what it actually remembers. Ro''s answer here: the hot decade. Expulsion''s: 11 Ma exactly. Present values alone collapse three diaries into one line and lose the plot.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 1, 'The fixture''s complete charge statement reads, in fractions:', '["conversion 0.535, expulsion efficiency 0.742 and delivered-of-potential 0.721.", "conversion 0.742, expulsion efficiency 0.721, delivered-of-potential 0.535.", "conversion 0.721, efficiency 0.535, delivered 0.742.", "all three equal at 0.742."]'::jsonb, 1, '13946.55/18786.41, 10048.99/13946.55 and 10048.99/18786.41. Three different denominators, three different statements.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 2, 'The mass still held in the source''s pores at present day is', '["764.78 kg/m2, the squeeze residue.", "4662.34280519763 kg/m2, the rock filled exactly to its cap''s brim.", "zero: everything generated was expelled.", "3897.561036418822 kg/m2, below the regrown cap''s brim."]'::jsonb, 3, 'Generated minus expelled. The rock holds LESS than its cap allows because the squeeze took extra while the bucket was small, and the difference is the 764.78 residue.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 3, 'Ten thousand kg/m2 of expelled mass over a 20 x 30 km kitchen is roughly', '["six billion tonnes, of order forty billion barrels of oil equivalent.", "six million tonnes.", "sixty thousand barrels.", "not convertible to field terms without the migration losses being specified first."]'::jsonb, 0, 'Ten million tonnes per km2 times 600 km2. Real accumulations capture single-digit percentages after migration, so the order-of-magnitude check is what the statement must survive.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 4, 'The expulsion window of this basin is best summarised as', '["20 to 10 Ma, the hot decade of the erosion event''s phantom section.", "0 to 150 Ma, continuous.", "effectively 80 to 60 Ma, 77 percent complete by 60 Ma.", "80 Ma exactly, one step."]'::jsonb, 2, 'A final squeeze increment at 11 Ma. The dates are the statement''s sharpest commercial content: a trap formed at 40 Ma missed three quarters of the charge.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 5, 'A trap formed at 40 Ma received, of this kitchen''s expelled mass,', '["nothing at all.", "the full 10049 kg/m2 of the kitchen''s delivery.", "only what was expelled after 40 Ma.", "exactly half."]'::jsonb, 2, 'About 1650 kg/m2 of the 10049 total. Expelled stood at 8398.309 by 40 Ma; the remainder, 10048.985 - 8398.309, is what post-dates the trap. Mass without coincidence charges nothing.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 6, 'What the charge statement deliberately does not claim is', '["anything about migration pathways, trap volumes, seals or preservation.", "the timing of expulsion relative to each of the basin''s trap-forming episodes.", "the retained mass.", "the conversion fraction."]'::jsonb, 0, 'The model ends at the source''s door. Charge is necessary, never sufficient, and the statement bounds the system from above and times it.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 7, 'Steady-per-step heat would have been adequate for', '["no part of the run.", "the arrival steps at 120 and 80 Ma.", "the removal step at 10 Ma.", "the graded final temperature."]'::jsonb, 3, 'The last ten megayears are geometrically quiet. Quiet endings converge: transient and steady coincide at 149.76 within tolerance. The events are where the two treatments part.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 8, 'At depositional arrivals, a steady model would', '["under-heat them.", "over-heat the catch-up years, jumping straight to the settled answer.", "match the transient solution exactly, both treatments being converged there.", "crash on the discontinuity."]'::jsonb, 1, 'The real column lags cold sediment; steady skips the lag. At the removal the sign flips: steady snaps cold and deletes the warm tail.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 9, 'The timescale comparison that decides whether transient heat matters is', '["pace of geological change against the column''s conductive relaxation time.", "step size against the basin''s age.", "heat flow against radiogenic production.", "burial rate against sedimentation rate, layer by layer through the whole stack."]'::jsonb, 0, 'Change faster than relaxation demands transient treatment. Real basins put most maturation in their fast-change eras, which is why serious models are transient.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 10, 'The register''s six entries are', '["six numerical tolerances.", "instant deposition, elastic rebound, inferred phantom history, layer-centre kinetics.", "the six graded fields.", "the six verification checks of the workflow''s third step, listed in rising cost order."]'::jsonb, 1, 'One-way bucket, no migration. Each named where it acted, each with a footprint and a remedy. A modeller is exactly as trustworthy as their limitations list.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 11, 'Which conclusion is register-sensitive rather than robust?', '["The sign of the erosion signature.", "The generation identity M_gen = M_pot x TR.", "Post-event retention behaviour.", "The potential''s closed form."]'::jsonb, 2, 'Depends on the rebound convention. The regrown bucket is elastic rebound''s doing; hysteresis would keep it squeezed. The identities and the signature''s sign survive every register entry.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 12, 'A reviewer attacks the expelled mass''s five significant figures. The register-based reply is', '["the figures should indeed be truncated.", "the figures are rounded from the oracle.", "five-figure precision is merely a formatting convention that the capstone''s grader imposes.", "precision is the model''s, exactly; the register prices what the world may do differently."]'::jsonb, 3, 'Both travel together. The identity behind the number is reproducible arithmetic; the physical uncertainty lives in named register entries with priced sensitivities.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 13, 'The three closed-form identities that verify half the graded surface are', '["the three solid thicknesses.", "the two anchors and the signature.", "three steady-state temperature checks, read at each of the three sand-to-shale boundaries.", "the potential, the generation product."]'::jsonb, 3, 'The 11 Ma expulsion subtraction. Three multiplications and a subtraction, all calculator work, catching wrong constants, wrong stacks and wrong retention arithmetic before any interpretation.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 14, 'The two-run discipline requires the with-event and no-event runs to be identical before 20 Ma because', '["heat flow is constant before 20 Ma.", "the engine caches the first 130 steps.", "the phantom does not exist yet.", "the source is immature before 20 Ma."]'::jsonb, 2, 'Any earlier divergence proves the runs differ in more than the event. A signature is a measurement of one cause only if the runs differ in exactly that cause. Earlier divergence contaminates it.'),
  ('basin', 'advanced', 'module', 'm05-what-the-model-buys', 15, 'A modified run shows expelled up 181 kg with TR unchanged. The checklist localises the change to', '["the kerogen spectrum.", "the cap history: retention constants, rebound convention or phantom geometry.", "the heat-flow history, whose youngest points control the final expulsion steps.", "the potential''s TOC."]'::jsonb, 1, 'Unchanged TR and potential fix generation, so only the cap side of the expulsion identity can have moved. Check cap(11 Ma) against 3858.026119789524 first.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 1, 'The workflow''s five steps are', '["run, calibrate, tune, report, archive.", "assemble, run the comparisons, verify.", "geometry, heat, kinetics, mass and then migration, run in pipeline order per step.", "input, output, review, publish, close."]'::jsonb, 1, 'The diaries, state the charge. The three tiers run as one sequence, twice, with the checks between the running and the reading.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 2, 'The workflow''s unit of meaning is', '["the panel''s tile grid.", "the single reference run, everything else being sensitivity decoration.", "the calibration well.", "the comparison set: a reference run plus runs isolating causes."]'::jsonb, 3, 'Difference per pair. One run answers only "what does this model say". Differences answer "what does this cause do", and only those transfer from model to basin.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 3, 'In practice the adjustment order when calibration fails is', '["geometry first, heat flow last.", "heat flow first, since it is the free parameter.", "kinetics first, being the most sensitive.", "whichever moves the answer fastest."]'::jsonb, 0, 'The kinetics never. Geometry is the best observed and heat the least; the published kinetics are the cross-basin standard that makes calibration meaningful at all.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 4, 'The tell that heat flow is compensating a geometry error is', '["residuals that average to zero.", "a heat-flow history that cools with time much faster than rift decay physically allows.", "a beautifully fitted calibration well surrounded by mis-predicted neighbours.", "a signature that goes negative."]'::jsonb, 2, 'Two errors cancel at one well and disagree everywhere else. Holdout wells, exactly cross-validation, expose it.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 5, 'An erosion amount asserted without a maturity residual demanding it is', '["required by the phantom convention.", "conservative practice.", "decoration, not inference.", "harmless if under 600 m."]'::jsonb, 2, 'The signature machinery is the honest constraint. Missing section is inferred from excess maturity through the sensitivity curve, with its error bars. Otherwise it is a free parameter wearing a geological costume.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 6, 'Study reproducibility requires', '["versioned inputs, recorded twins for every difference.", "a single archived final run.", "the panel''s screenshots.", "the engine''s source code alone, all results being regenerable from it."]'::jsonb, 0, 'A one-line register per run. Fifty undocumented runs have one result: their numbers cannot be audited. The engine side is already handled by committed goldens; the study side is yours.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 7, 'On the capstone, the two runs are', '["the engine against the oracle.", "two random erosion amounts.", "the project at two heat-flow histories.", "the golden project as given."]'::jsonb, 3, 'The same project with the erosion list empty. Verify the two-run discipline and the three identities, then read the six fields.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 8, 'Reading the expelled-mass field from present-day generation minus the present cap gives', '["the graded value 10048.985378825158, through the expulsion identity.", "9284.204, which misses the graded value by 153 tolerances.", "a value inside tolerance.", "the no-event run''s answer."]'::jsonb, 1, 'The monotone rule set the answer at 11 Ma, under the squeezed cap. The present-day subtraction is the classic error the squeeze lesson exists to prevent.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 9, 'The signature field''s classic sign error is', '["reporting without-minus-with.", "using the source''s top instead of its centre.", "differencing TR instead of Ro.", "quoting the rounded 0.0567 instead of the full-precision signature value."]'::jsonb, 0, 'Negative number. The definition is with-minus-without, positive. The rounded 0.0567 actually sits inside the 0.001 tolerance; the sign does not.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 10, 'Carrying TR at full precision into the generated-mass multiplication matters because', '["the engine silently truncates TR at four significant digits unless told otherwise.", "one 0.002 of TR is worth 37.57 kg/m2 against the 5 kg/m2 mass tolerance.", "the potential is only known roughly.", "rounding is forbidden by the register."]'::jsonb, 1, 'The mass is graded seven times tighter than the TR tolerance implies, which effectively mandates the exact multiplication route.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 11, 'The flank-block task (source 400 m shallower) is phrased as the workflow by', '["scaling the reference answers by depth ratio.", "re-running the reference model at a proportionally higher basal heat-flow history instead.", "cloning the description with the one change and differencing against the reference.", "asking the panel for a new erosion amount."]'::jsonb, 2, 'One difference per comparison. The potential must not move, since richness and grain are unchanged, and that check rides along free.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 12, 'The basin ladder''s three capabilities, in one line each, are', '["beginner geometry, intermediate calibration and advanced uncertainty, in rising order of grammar.", "maps, logs and seismic.", "porosity, temperature and pressure.", "hand-checkable burial and heat; kinetics on given histories; forward-modelled charge."]'::jsonb, 3, 'Each tier makes the one below more demanding rather than replacing it, and each was learned where it could be checked alone.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 13, 'The geoscience path''s actual curriculum, per the closing lesson, is', '["software proficiency.", "all ten of the capstone answer keys, memorised at full precision together with their tolerances.", "petroleum systems terminology.", "demanding fixtures, closed forms and independent implementations before trusting any number."]'::jsonb, 3, 'Conventions carried alongside. The discipline transfers to every tool; the formulas are its exercises.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 14, 'Beyond this course, in the model''s own direction, lie', '["new reflectance formulas beyond Easy%Ro for unconventional basins.", "faster processors.", "migration and trap-fill, distributional uncertainty.", "deeper fixtures."]'::jsonb, 2, 'Multi-well calibration studies. None of it needs a new kind of thinking; all of it needs the habits the thirty tiers drilled.'),
  ('basin', 'advanced', 'module', 'm06-the-charge-workflow', 15, 'The six Expert capstone values, in order, are', '["1.6151780693528823; 149.76027256253775; 0.7160858054928011; 13452.68; 8790.34; 0.", "1.6718288798752388; 149.76037539670858; 0.7423743797385286; 13946.54641524398; 10048.985378825158; 0.05665081052235643.", "0.9871413464062039; 150; 0.05477927380797565; 18786.41; 4662.34; 0.0567.", "1.6718; 168.51; 0.7424; 13947; 10049; 0.0144."]'::jsonb, 1, 'Ro, temperature, TR, generated, expelled, signature. The second option is the no-event run''s set, the third mixes Professional values with this tier''s constants, and the fourth swaps in the hot-decade peak and the 300 m signature.'),
  ('basin', 'advanced', 'final', null, 1, 'The forward model''s inputs are', '["a temperature track per layer.", "stratigraphy with ages, source richness, surface temperature, a heat-flow history and erosion events.", "measured reflectance profiles.", "the Professional tier''s golden ramp tables, one temperature track per layer of the stack."]'::jsonb, 1, 'The model produces the temperature tracks itself; measured maturity is what it is calibrated against, not an input.'),
  ('basin', 'advanced', 'final', null, 2, 'The engine steps time at', '["variable steps chosen by the solver''s error control.", "0.01 Ma throughout.", "10 Ma steps, refined to 1 Ma in the neighbourhood of each event.", "1 Ma, from the oldest ageStart down to zero."]'::jsonb, 3, 'DT_MA = 1. The fine 0.01 Ma convention belongs to the kinetics fixtures of the tier below.'),
  ('basin', 'advanced', 'final', null, 3, 'Present-day model geometry matches the well''s tops exactly because', '["solid thicknesses were derived from the present stack.", "the thermal solver iterates the stack until the tops match the well.", "the tops are re-imposed each step.", "of a fortunate coincidence of the compaction parameters."]'::jsonb, 0, 'The model there. Anchored by construction: the observable stack is converted to conserved grain once, so predictions live entirely in the past.'),
  ('basin', 'advanced', 'final', null, 4, 'The Mid Sand''s 1200 m arrive at', '["80 Ma, with the Upper Shale.", "spread across 120 to 80 Ma.", "120 Ma, in one step.", "140 Ma, on the source."]'::jsonb, 2, 'Instant deposition at ageStart. Its window''s end, 80 Ma, is when the NEXT layer starts.'),
  ('basin', 'advanced', 'final', null, 5, 'Just before the Upper Shale lands, the source''s centre temperature is about 88 degC; just after, 153 and climbing. The climb continues because', '["the source rock itself generates heat as its kerogen reacts all through the window.", "the heat flow rises at 80 Ma.", "backward Euler relaxes the column toward the new steady profile over many steps.", "the phantom layer''s arrival at 20 Ma is already warming the whole column from below."]'::jsonb, 2, 'The first estimate undershot the insulating effect of 1600 m of fresh shale; the transient catches up through 161.38 and 164.38 over the following steps.'),
  ('basin', 'advanced', 'final', null, 6, 'The temperatures the kinetics consume are', '["one per layer per step, interpolated at the layer''s centre depth.", "the maximum across the layer.", "cell-by-cell values across the thermal grid, one kinetic state per cell.", "the surface temperature plus a fixed regional gradient applied to layer depth."]'::jsonb, 0, 'One kinetic state per layer, one representative temperature. A 400 m source spans about ten internal degrees the single value cannot see.'),
  ('basin', 'advanced', 'final', null, 7, 'The thermal grid''s cells are', '["sized in proportion to the step.", "one per layer.", "exactly one metre tall in every layer.", "at most 100 m tall per layer."]'::jsonb, 3, 'Porosity-blended properties. MAX_CELL_M = 100. Conductivity and heat capacity blend matrix with pore water by the cell''s Athy porosity, so depth changes thermal structure even at fixed lithology.'),
  ('basin', 'advanced', 'final', null, 8, 'The heat flow the model uses at 75 Ma is', '["70 mW/m2, held from the 100 Ma point until the next one is reached.", "67.5 mW/m2, interpolated between the 100 and 50 Ma points.", "65 mW/m2, the value carried at the 50 Ma point of the history.", "61 mW/m2."]'::jsonb, 1, 'Halfway down the 70-to-65 segment. The 61 value belongs to 10 Ma.'),
  ('basin', 'advanced', 'final', null, 9, 'The phantom layer exists from', '["20 Ma until its removal at 10 Ma.", "80 to 10 Ma.", "10 Ma to present.", "150 to 140 Ma."]'::jsonb, 0, 'Deposited at the youngest pre-event ageEnd, the Upper Shale''s 20 Ma, and removed at the event age.'),
  ('basin', 'advanced', 'final', null, 10, 'While the phantom exists, it', '["adds a pure temperature increment to the whole column, skipping the geometric bookkeeping entirely.", "deepens, compacts and heats everything beneath it like any real layer, but is never reported.", "is visible in the burial outputs.", "runs its own generation."]'::jsonb, 1, 'Mechanically real, reportingly invisible. A bare temperature nudge would reproduce none of its mechanical bookkeeping.'),
  ('basin', 'advanced', 'final', null, 11, 'The source''s deepest-ever position, bottom at 3519.372263771036 m, was held', '["at 76 Ma.", "at present day.", "through the phantom decade, ages 20 down to 11 Ma.", "for a single step at the 10 Ma removal, between the two geometries."]'::jsonb, 2, 'The phantom''s overburden pushed it there and the removal at 10 Ma rebounded it to today''s 3200.'),
  ('basin', 'advanced', 'final', null, 12, 'The two runs'' present-day source temperatures, 149.76037539670858 and 149.76027256253775, demonstrate', '["that the erosion event never affected the source''s temperature at any point of the run.", "a convergence failure of the backward Euler thermal solver at the final steps.", "the erosion signature itself.", "that every present-day thermal observable has forgotten the event completely."]'::jsonb, 3, 'The event moved temperature by 13-plus degrees while it lasted; ten quiet megayears erased the difference to a ten-thousandth. The signature lives in reflectance, not temperature.'),
  ('basin', 'advanced', 'final', null, 13, 'The final reflectances of the two runs are', '["0.9871413464062039 with the event and 1.1129254516555198 without it.", "1.6151780693528823 with the event and 1.6718288798752388 without it.", "identical, as with temperature.", "1.6718288798752388 with the event, 1.6151780693528823 without."]'::jsonb, 3, 'The event ADDS maturity, so with sits above without. The 0.987/1.113 pair belongs to the Professional ramps.'),
  ('basin', 'advanced', 'final', null, 14, 'The erosion signature''s graded value and tolerance are', '["0.05665081052235643, to 0.0001.", "0.0567, to 0.01.", "0.05665081052235643, to 0.001.", "0.1529442446507306, to 0.001."]'::jsonb, 2, 'With-minus-without on final source Ro. The 0.1529 signature belongs to the 900 m sensitivity case.'),
  ('basin', 'advanced', 'final', null, 15, 'Moving the erosion event from 10 Ma to 100 Ma would make the signature', '["smaller, since the younger basin had accumulated less section to lose.", "several times larger: hotter heat flow.", "zero, since Ro resets at events.", "unchanged, since an erosion signature depends only on the amount of section removed."]'::jsonb, 1, 'Less drained ladder, faster front. An event''s kinetic mark depends on when it interrupts maturation. The 0.0566 is small precisely because this event came late over a stalled source.'),
  ('basin', 'advanced', 'final', null, 16, 'The signature-versus-amount curve''s convexity means', '["large vanished sections are disproportionately visible and small ones disproportionately invisible.", "eroded amounts recover linearly from measured signatures across the whole range, 300 m per 0.028 of Ro.", "the curve saturates by 600 m.", "signatures are independent of amount."]'::jsonb, 0, 'Per-metre worth triples from the first 300 m to the third: 0.000048, then 0.00014, then 0.00032 of Ro per metre.'),
  ('basin', 'advanced', 'final', null, 17, 'Inverting a measured signature of 0.057 plus or minus 0.01 recovers the amount as', '["600 m exactly.", "about 600 m with roughly plus or minus 50 m.", "anywhere at all between 0 and 900 m at that measurement scatter.", "300 m, carrying the same error bar as at 600."]'::jsonb, 1, 'Steep local slope converting Ro precision into tight section estimates. The slope near 600 m is about 0.0002 of Ro per metre. The same Ro uncertainty around a 300 m event spans well over 100 m of amount.'),
  ('basin', 'advanced', 'final', null, 18, 'The source''s generative potential is', '["18786.405883452077 kg/m2.", "13946.54641524398 kg/m2.", "10048.985378825158 kg/m2, its lifetime delivery through the expulsion valve.", "4662.34280519763 kg/m2."]'::jsonb, 0, '2720 x 345.33834344581027 x 0.04 x 0.5. The closed form and the panel''s QC tile. The other three are the generated mass, the expelled mass and the present cap.'),
  ('basin', 'advanced', 'final', null, 19, 'A leaner source at TOC 2 and HI 300 in the same geometry would carry a potential of', '["the same 18786 kg/m2.", "about 9393 kg/m2, half.", "about 5636 kg/m2, thirty percent of the fixture''s.", "about 1879 kg/m2, one tenth of the fixture''s inventory."]'::jsonb, 2, 'Richness enters linearly twice: 0.5 x 0.6 = 0.3 of the original. No downstream sophistication recovers mass that was never there.'),
  ('basin', 'advanced', 'final', null, 20, 'Generated mass and final TR are related by', '["the vitrinite F.", "the retention cap.", "an integral of the conversion rate over the full burial history.", "one exact multiplication through the constant potential."]'::jsonb, 3, 'M_gen = M_pot x TR at every step. Getting one graded field right makes the other free, and an error in either exposes both.'),
  ('basin', 'advanced', 'final', null, 21, 'Essentially all of this basin''s generation happened', '["between 80 and 40 Ma, driven by the Upper Shale''s burial under strong early heat flow.", "during the phantom decade, at the basin''s lifetime temperature maximum, 20 down to 11 Ma.", "before 100 Ma.", "in the last ten megayears."]'::jsonb, 0, 'TR reached 0.66 by 60 Ma and 0.71 by 20 Ma. The hot decade added under 4 percent; the endgame nearly nothing.'),
  ('basin', 'advanced', 'final', null, 22, 'The retention cap at the source''s present geometry is', '["850 kg/m2.", "3858.026119789524 kg/m2, computed on the phantom decade''s deeper, thinner geometry.", "32970 kg/m2.", "4662.34280519763 kg/m2."]'::jsonb, 3, '400 m x phiAvg 0.13712772956463615 x 0.1 x 850. The squeezed 3858 belongs to the phantom decade''s geometry, and 32970 to the freshly deposited source at the surface.'),
  ('basin', 'advanced', 'final', null, 23, 'The expulsion saturation threshold and reference HC density are', '["0.5 of pore saturation at the 1030 kg/m3 formation water density.", "0.1 and 850 kg/m3, spec constants of the retention model.", "0.1 and 1030 kg/m3.", "fitted per basin."]'::jsonb, 1, 'Ten percent pore saturation before primary migration connects, at the 850 reference density. 1030 is the formation water density, a different constant.'),
  ('basin', 'advanced', 'final', null, 24, 'Expelled mass through time is computed as', '["generated minus the current cap, whatever its sign.", "generated times the efficiency.", "the running maximum of generated-minus-cap.", "the cap''s deficit integrated over time."]'::jsonb, 2, 'max(previous, gen - cap): a one-way valve. Oil that left the source does not climb back in when the bucket regrows.'),
  ('basin', 'advanced', 'final', null, 25, 'The final expelled mass was determined at', '["80 Ma, when the first expulsion left.", "present day.", "11 Ma, the last squeezed step.", "10 Ma, the removal step."]'::jsonb, 2, 'Nothing after changed it. gen(11) minus cap(11) equals 10048.985378825158 exactly; the 10 Ma rebound dropped gen-minus-cap below the standing maximum.'),
  ('basin', 'advanced', 'final', null, 26, 'The event''s charge contribution splits as', '["1258.65 of extra generation only.", "764.78 kg/m2 of squeeze and 493.87 kg/m2 of extra generation.", "629 kg/m2 from each mechanism.", "493.87 kg/m2 of cap squeeze and 764.78 kg/m2 of extra hot-decade generation."]'::jsonb, 1, 'Three fifths mechanical, two fifths kinetic. The habit it corrects: erosion events discussed only as maturity anecdotes.'),
  ('basin', 'advanced', 'final', null, 27, 'The expulsion efficiency of this kitchen is', '["0.1, the expulsion saturation threshold itself.", "0.7423743797385286.", "0.5349072856813322.", "0.7205357569986879, expelled over generated."]'::jsonb, 3, '10048.985378825158 / 13946.54641524398. The 0.742 is conversion and the 0.535 is delivered-of-potential: same numerators and denominators, different pairings.'),
  ('basin', 'advanced', 'final', null, 28, 'A trap formed at 90 Ma, before the Upper Shale,', '["waited through the entire charge and could receive all of it.", "missed everything.", "received only the 11 Ma squeeze increment of the kitchen''s delivery.", "cannot be evaluated by the model."]'::jsonb, 0, 'Expulsion began at 80 Ma; structure older than the window sees the full delivery. Timing, not totals, separates charged prospects from dry ones.'),
  ('basin', 'advanced', 'final', null, 29, 'The steady-versus-transient verdict on this fixture''s graded values is', '["only the signature survives.", "all six of the graded values survive a steady treatment unchanged.", "none survive.", "final temperature provably survives; the rest shift by unverifiable amounts."]'::jsonb, 3, 'Quiet endings converge; arrival lags and the removal''s warm tail accumulate into the kinetic integrals. That shape is general for shortcut arguments.'),
  ('basin', 'advanced', 'final', null, 30, 'The model''s limitations register matters because', '["it separates convention-robust conclusions from convention-sensitive ones.", "reviewers require one.", "it lists the engine''s complete version history for the auditors.", "it shortens the report."]'::jsonb, 0, 'Each entry implies the sensitivity experiment that bounds it. Silence hides the bends; blanket disclaimers price nothing.'),
  ('basin', 'advanced', 'final', null, 31, 'Which pair belongs to the same monotone diary?', '["The 80 Ma temperature spike and the present temperature.", "The hot decade''s Ro gain and the present-day signature.", "The cap at 11 Ma and the cap at 10 Ma.", "The heat flow at 150 and at 0 Ma."]'::jsonb, 1, 'Both are entries of the maturity ratchet, the second being the first preserved for ten megayears. Temperature and cap series are memoryless states.'),
  ('basin', 'advanced', 'final', null, 32, 'The composition check unique to the forward model is', '["monotone TR.", "the two reflectance anchors.", "the final profile agreeing with a steady solve of the final geometry.", "the solid-thickness integral, checked against every layer''s present geometry."]'::jsonb, 2, 'The ending is quiet. Inherited checks bound the stages; the composition checks test the stages feeding each other, and the quiet-ending convergence is the cheapest of them.'),
  ('basin', 'advanced', 'final', null, 33, 'A run whose no-event twin differs from it at 50 Ma proves', '["the runs differ in something besides the event.", "the event''s effects begin early.", "the phantom was deposited at 50 Ma.", "numerical noise accumulating at entirely acceptable levels."]'::jsonb, 0, 'Their difference measures nothing. The phantom does not exist until 20 Ma. The two-run discipline is what makes a difference a measurement.'),
  ('basin', 'advanced', 'final', null, 34, 'The reference basin''s stratigraphic ages imply the source has existed for', '["120 Ma.", "150 Ma, the basin''s full span.", "140 of the basin''s 150 Ma.", "80 Ma."]'::jsonb, 2, 'Deposited at 140 Ma, ten megayears after Base Sand opened the basin.'),
  ('basin', 'advanced', 'final', null, 35, 'The graded final TR of 0.7423743797385286 means', '["the vitrinite ladder is 74 percent drained at the source''s present-day maturity.", "the source is exhausted.", "74 percent of generated oil was expelled.", "about a quarter of the source''s potential remains unconverted at present day."]'::jsonb, 3, 'TR is conversion of the kerogen potential. Expelled-over-generated is the 0.721 efficiency, and the vitrinite state is a different clock entirely.'),
  ('basin', 'advanced', 'final', null, 36, 'The panel''s potential tile never moves with the erosion control because', '["the panel caches it.", "the potential is computed from the present stack''s conserved grain and richness.", "the erosion event happens long after the source''s generation has effectively finished.", "the tile is hard-coded."]'::jsonb, 1, 'No event touches. Solid thickness is invariant and TOC and HI are inputs. That immovability is what makes the tile a QC anchor.'),
  ('basin', 'advanced', 'final', null, 37, 'Instant deposition makes the model''s generation onset dates', '["read systematically later than the rock experienced them.", "read sharper than the rock experienced them.", "exactly correct.", "unreadable."]'::jsonb, 1, 'The 80 Ma step performs sixty megayears of burial, so onsets compress toward event ages. Never date onset more precisely than the convention resolves.'),
  ('basin', 'advanced', 'final', null, 38, 'The charge statement''s honest precision practice is', '["tolerance-width rounding.", "two significant figures everywhere, matching laboratory practice.", "full precision for the computed, register-priced uncertainty for the physical.", "the oracle''s digits."]'::jsonb, 2, 'The identity behind each number is exact arithmetic; the physical error bars come from named register entries and their sensitivity runs.'),
  ('basin', 'advanced', 'final', null, 39, 'Which basin observation would the ratchet let you infer vanished section from?', '["Measured maturity consistently above any model of the preserved stack.", "Present-day log temperatures sitting consistently above the regional geothermal gradient.", "A thick condensed section.", "Seismic amplitude dimming."]'::jsonb, 0, 'Excess Ro is the erosion signature read in reverse, with the amount-sensitivity curve as the calibration. Present temperatures forget; reflectance testifies.'),
  ('basin', 'advanced', 'final', null, 40, 'The final lesson places this course as', '["an optional elective.", "the first of the engineering ladders.", "a prerequisite for Rock Physics.", "the last rung of the last ladder."]'::jsonb, 3, 'With basin complete, the ten-app geoscience path is deep at every tier. Nine courses described the subsurface as it is; this one described how it came to be, and its Expert close completes the path.'),
  ('basin', 'advanced', 'final', null, 41, 'The deepest habit the ladder teaches, restated at its close, is', '["always preferring the newest release of the modelling software over the validated older one.", "running every model twice.", "demanding fixtures, closed forms and independent implementations before trusting numbers.", "memorising the capstone keys."]'::jsonb, 2, 'Conventions carried alongside. Run-twice is one instrument of it. The habit is the checkable-number discipline that transfers to every tool after this one.'),
  ('basin', 'advanced', 'final', null, 42, 'Expelled mass at 60 Ma stood at 7735.058 kg/m2, which as a share of the final charge is', '["100 percent.", "55 percent.", "7.7 percent, a tenth of the true share.", "77 percent: three quarters of the kitchen''s delivery predates 60 Ma."]'::jsonb, 3, '7735.058 / 10048.985 = 0.7697. The timing paragraph of the charge statement rests on reads like this.');
